  <style>
    :root {
      --green: #2D6A4F;
      --green-light: #40916C;
      --green-dark: #1B4332;
      --accent: #F4A261;
      --accent-light: #F7B87D;
      --cream: #FEFAE0;
      --cream-dark: #F5F0D7;
      --white: #FFFFFF;
      --gray-50: #FAFAF9;
      --gray-100: #F5F5F0;
      --gray-200: #E8E8E0;
      --gray-400: #A8A89A;
      --gray-600: #6B6B5E;
      --gray-800: #3D3D34;
      --gray-900: #1A1A14;
      --radius-sm: 8px;
      --radius: 12px;
      --radius-lg: 20px;
      --shadow-sm: 0 2px 8px rgba(0,0,0,0.06);
      --shadow: 0 4px 16px rgba(0,0,0,0.08);
      --shadow-lg: 0 8px 32px rgba(0,0,0,0.10);
      --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
    }

    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', system-ui, -apple-system, sans-serif;
      background: var(--cream);
      color: var(--gray-800);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    h1, h2, h3, h4 { font-family: 'Nunito', sans-serif; font-weight: 800; line-height: 1.2; }

    /* ── Header ─────────────────────────── */
    .header {
      position: sticky; top: 0; z-index: 100;
      background: rgba(255,255,255,0.92); backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
      padding: 0 24px;
    }
    .header-inner {
      max-width: 1200px; margin: 0 auto;
      display: flex; align-items: center; justify-content: space-between;
      height: 68px;
    }
    .logo {
      font-family: 'Nunito', sans-serif; font-weight: 900; font-size: 1.5rem;
      color: var(--green); display: flex; align-items: center; gap: 8px;
      text-decoration: none;
    }
    .logo-icon { font-size: 1.6rem; }
    .nav { display: flex; gap: 32px; list-style: none; }
    .nav a {
      text-decoration: none; color: var(--gray-600); font-weight: 600; font-size: 0.95rem;
      transition: color var(--transition); position: relative;
    }
    .nav a:hover { color: var(--green); }
    .nav a::after {
      content: ''; position: absolute; bottom: -4px; left: 0; width: 0; height: 2px;
      background: var(--accent); transition: width var(--transition);
    }
    .nav a:hover::after { width: 100%; }
    .menu-toggle { display: none; background: none; border: none; cursor: pointer; padding: 4px; }
    .menu-toggle span { display: block; width: 24px; height: 2px; background: var(--gray-800); margin: 5px 0; transition: var(--transition); border-radius: 2px; }

    /* ── Sections ──────────────────────── */
    .section { padding: 80px 24px; }
    .section-inner { max-width: 1200px; margin: 0 auto; }
    .section-label {
      display: inline-block; background: var(--accent); color: var(--white);
      font-weight: 700; font-size: 0.8rem; text-transform: uppercase;
      letter-spacing: 0.06em; padding: 6px 16px; border-radius: 20px; margin-bottom: 16px;
    }
    .section-title { font-size: 2.5rem; color: var(--gray-900); margin-bottom: 12px; }
    .section-subtitle { font-size: 1.15rem; color: var(--gray-600); max-width: 580px; }

    /* ── Hero ───────────────────────────── */
    .hero {
      padding: 100px 24px 120px;
      background: linear-gradient(160deg, #FEFAE0 0%, #E8F5E9 40%, #FFF8E1 100%);
      position: relative; overflow: hidden;
    }
    .hero::before {
      content: ''; position: absolute; top: -80px; right: -120px;
      width: 500px; height: 500px; border-radius: 50%;
      background: radial-gradient(circle, rgba(45,106,79,0.06) 0%, transparent 70%);
    }
    .hero::after {
      content: ''; position: absolute; bottom: -60px; left: -80px;
      width: 400px; height: 400px; border-radius: 50%;
      background: radial-gradient(circle, rgba(244,162,97,0.08) 0%, transparent 70%);
    }
    .hero-inner {
      max-width: 1200px; margin: 0 auto;
      display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
      position: relative; z-index: 1;
    }
    .hero-content { max-width: 540px; }
    .hero-tag {
      display: inline-flex; align-items: center; gap: 6px;
      background: var(--white); color: var(--green);
      font-weight: 700; font-size: 0.85rem; padding: 8px 18px;
      border-radius: 20px; margin-bottom: 24px;
      box-shadow: var(--shadow-sm);
    }
    .hero h1 { font-size: 3.5rem; color: var(--gray-900); margin-bottom: 16px; line-height: 1.1; }
    .hero h1 span { color: var(--green); display: block; }
    .hero p { font-size: 1.2rem; color: var(--gray-600); margin-bottom: 32px; }
    .hero-buttons { display: flex; gap: 14px; flex-wrap: wrap; }
    .btn {
      display: inline-flex; align-items: center; gap: 8px;
      font-family: 'Nunito', sans-serif; font-weight: 700; font-size: 1rem;
      padding: 14px 28px; border-radius: 50px; border: none; cursor: pointer;
      text-decoration: none; transition: all var(--transition);
    }
    .btn-primary { background: var(--green); color: var(--white); }
    .btn-primary:hover { background: var(--green-dark); transform: translateY(-2px); box-shadow: 0 6px 20px rgba(45,106,79,0.3); }
    .btn-outline { background: var(--white); color: var(--green); border: 2px solid var(--green); }
    .btn-outline:hover { background: var(--green); color: var(--white); transform: translateY(-2px); }
    .hero-visual {
      display: grid; grid-template-columns: 1fr 1fr; gap: 16px; grid-template-rows: 180px 180px;
    }
    .hero-card {
      background: var(--white); border-radius: var(--radius-lg); padding: 24px;
      box-shadow: var(--shadow); display: flex; flex-direction: column;
      align-items: center; justify-content: center; text-align: center;
      transition: transform var(--transition);
    }
    .hero-card:hover { transform: translateY(-4px); }
    .hero-card-icon { font-size: 2.5rem; margin-bottom: 8px; }
    .hero-card-label { font-weight: 700; font-size: 0.9rem; color: var(--green); }
    .hero-card:nth-child(1) { grid-row: span 2; }
    .hero-card:nth-child(1) .hero-card-icon { font-size: 4rem; }

    /* ── Featured Products Carousel ─────── */
    #featured-products { background: var(--white); }
    .carousel-wrap { position: relative; margin-top: 40px; }
    .carousel-viewport { overflow: hidden; margin: 0 52px; }
    .carousel-track {
      display: flex; gap: 20px; transition: transform 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    }
    .product-card {
      flex: 0 0 calc(25% - 15px); min-width: 240px;
      background: var(--gray-50); border-radius: var(--radius-lg);
      overflow: hidden; box-shadow: var(--shadow-sm);
      transition: transform var(--transition), box-shadow var(--transition);
    }
    .product-card:hover { transform: translateY(-6px); box-shadow: var(--shadow-lg); }
    .product-img {
      height: 200px; display: flex; align-items: center; justify-content: center;
      font-size: 4rem; position: relative;
    }
    .product-img::after {
      content: ''; position: absolute; inset: 0;
      background: linear-gradient(180deg, transparent 60%, rgba(0,0,0,0.03) 100%);
    }
    .product-body { padding: 20px; }
    .product-name { font-family: 'Nunito', sans-serif; font-weight: 700; font-size: 1.05rem; color: var(--gray-900); margin-bottom: 4px; }
    .product-desc { font-size: 0.85rem; color: var(--gray-400); margin-bottom: 12px; }
    .product-price { font-family: 'Nunito', sans-serif; font-weight: 800; font-size: 1.25rem; color: var(--green); }

    .carousel-btn {
      position: absolute; top: 50%; transform: translateY(-50%);
      width: 44px; height: 44px; border-radius: 50%;
      background: var(--white); border: 2px solid var(--gray-200);
      cursor: pointer; font-size: 1.1rem; color: var(--gray-600);
      display: flex; align-items: center; justify-content: center;
      transition: all var(--transition); z-index: 10;
    }
    .carousel-btn:hover { background: var(--green); color: var(--white); border-color: var(--green); }
    .carousel-btn:disabled { opacity: 0.3; cursor: not-allowed; }
    .carousel-btn:disabled:hover { background: var(--white); color: var(--gray-600); border-color: var(--gray-200); }
    .carousel-btn.prev { left: 0; }
    .carousel-btn.next { right: 0; }

    /* ── Seasonal Picks ────────────────── */
    #seasonal-picks { background: linear-gradient(180deg, #FEFAE0 0%, #FFF8E1 100%); }
    .seasonal-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 20px; margin-top: 40px; }
    .seasonal-card {
      background: var(--white); border-radius: var(--radius-lg); padding: 28px 20px;
      text-align: center; box-shadow: var(--shadow-sm); transition: transform var(--transition);
    }
    .seasonal-card:hover { transform: translateY(-4px); }
    .seasonal-card-icon { font-size: 3rem; margin-bottom: 14px; }
    .seasonal-card h4 { font-size: 1rem; color: var(--gray-900); margin-bottom: 6px; }
    .seasonal-card p { font-size: 0.85rem; color: var(--gray-400); margin-bottom: 12px; }
    .seasonal-card .price { font-weight: 800; color: var(--accent); font-size: 1.15rem; }

    /* ── Categories ─────────────────────── */
    #categories { background: var(--white); }
    .cat-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 20px; margin-top: 40px; }
    .cat-card {
      position: relative; border-radius: var(--radius-lg); overflow: hidden;
      aspect-ratio: 1; cursor: pointer; box-shadow: var(--shadow-sm);
      transition: transform var(--transition), box-shadow var(--transition);
      display: flex; align-items: center; justify-content: center;
    }
    .cat-card:hover { transform: scale(1.05); box-shadow: var(--shadow-lg); }
    .cat-bg {
      position: absolute; inset: 0;
      display: flex; align-items: center; justify-content: center;
      font-size: 4rem; transition: transform var(--transition);
    }
    .cat-card:hover .cat-bg { transform: scale(1.1); }
    .cat-overlay {
      position: absolute; inset: 0;
      background: linear-gradient(180deg, rgba(13, 53, 35, 0.1) 0%, rgba(13, 53, 35, 0.7) 100%);
      display: flex; align-items: flex-end; padding: 24px;
      opacity: 0; transition: opacity var(--transition);
    }
    .cat-card:hover .cat-overlay { opacity: 1; }
    .cat-overlay h3 { color: var(--white); font-size: 1.2rem; font-weight: 800; margin-bottom: 4px; }
    .cat-overlay span { color: rgba(255,255,255,0.8); font-size: 0.8rem; }

    /* ── Brand Highlights ──────────────── */
    .highlights {
      background: var(--green); color: var(--white);
      padding: 70px 24px;
    }
    .highlights-inner { max-width: 1200px; margin: 0 auto; }
    .highlights-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 40px; text-align: center; }
    .stat-number { font-family: 'Nunito', sans-serif; font-weight: 900; font-size: 3rem; line-height: 1; margin-bottom: 8px; }
    .stat-label { font-weight: 600; font-size: 1.1rem; margin-bottom: 4px; opacity: 0.95; }
    .stat-desc { font-size: 0.85rem; opacity: 0.7; }

    /* ── Store Locator ─────────────────── */
    #store-locator { background: var(--white); }
    .locator-box { max-width: 680px; margin: 32px auto 0; }
    .locator-form { display: flex; gap: 10px; margin-bottom: 28px; }
    .locator-input {
      flex: 1; padding: 16px 24px; border: 2px solid var(--gray-200);
      border-radius: 50px; font-size: 1rem; font-family: inherit;
      outline: none; transition: border-color var(--transition);
    }
    .locator-input:focus { border-color: var(--green); }
    .locator-form .btn { padding: 14px 32px; flex-shrink: 0; }
    .store-results { display: none; }
    .store-results.visible { display: block; }
    .store-card {
      display: grid; grid-template-columns: 1fr auto auto; gap: 20px; align-items: center;
      background: var(--gray-50); padding: 20px 24px; border-radius: var(--radius);
      margin-bottom: 12px; box-shadow: var(--shadow-sm);
      transition: transform var(--transition);
    }
    .store-card:hover { transform: translateX(4px); }
    .store-name { font-family: 'Nunito', sans-serif; font-weight: 700; font-size: 1.05rem; color: var(--gray-900); }
    .store-addr { font-size: 0.9rem; color: var(--gray-600); }
    .store-hours { font-size: 0.85rem; color: var(--gray-400); }
    .store-dist { font-family: 'Nunito', sans-serif; font-weight: 800; color: var(--green); font-size: 1.1rem; white-space: nowrap; }
    .store-dist small { font-weight: 400; font-size: 0.8rem; color: var(--gray-400); }

    /* ── Newsletter ────────────────────── */
    #newsletter { background: linear-gradient(135deg, #E8F5E9 0%, #FEFAE0 100%); }
    .newsletter-box {
      max-width: 580px; margin: 0 auto; text-align: center;
      background: var(--white); padding: 52px 44px; border-radius: var(--radius-lg);
      box-shadow: var(--shadow-lg);
    }
    .newsletter-form { display: flex; gap: 10px; margin-top: 24px; }
    .newsletter-input {
      flex: 1; padding: 14px 20px; border: 2px solid var(--gray-200);
      border-radius: 50px; font-size: 1rem; font-family: inherit;
      outline: none; transition: border-color var(--transition);
    }
    .newsletter-input:focus { border-color: var(--green); }
    .newsletter-confirm { display: none; color: var(--green); font-weight: 700; margin-top: 16px; padding: 12px 20px; }

    /* ── Footer ────────────────────────── */
    .footer {
      background: var(--gray-900); color: var(--gray-400); padding: 60px 24px 32px;
    }
    .footer-inner { max-width: 1200px; margin: 0 auto; }
    .footer-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr 1fr; gap: 40px; margin-bottom: 48px; }
    .footer-brand .logo { font-size: 1.3rem; margin-bottom: 12px; }
    .footer-brand p { font-size: 0.9rem; color: var(--gray-400); }
    .footer h4 { color: var(--white); font-size: 0.9rem; font-weight: 700; margin-bottom: 16px; text-transform: uppercase; letter-spacing: 0.04em; }
    .footer ul { list-style: none; }
    .footer ul li { margin-bottom: 8px; }
    .footer ul a { color: var(--gray-400); text-decoration: none; font-size: 0.9rem; transition: color var(--transition); }
    .footer ul a:hover { color: var(--accent); }
    .footer-bottom {
      border-top: 1px solid rgba(255,255,255,0.08); padding-top: 24px;
      text-align: center; font-size: 0.85rem; color: var(--gray-400);
    }

    /* ── Responsive ────────────────────── */
    @media (max-width: 1024px) {
      .hero-inner { grid-template-columns: 1fr; text-align: center; }
      .hero-content { max-width: 100%; }
      .hero-buttons { justify-content: center; }
      .hero-visual { display: none; }
      .hero h1 { font-size: 2.5rem; }
      .product-card { flex: 0 0 calc(33.333% - 14px); }
      .cat-grid { grid-template-columns: repeat(3, 1fr); }
      .highlights-grid { grid-template-columns: repeat(2, 1fr); gap: 32px; }
      .footer-grid { grid-template-columns: 1fr 1fr 1fr; }
      .seasonal-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 768px) {
      .header-inner { height: 60px; }
      .nav { display: none; position: absolute; top: 60px; left: 0; width: 100%; flex-direction: column; background: var(--white); padding: 16px 24px; gap: 16px; border-bottom: 1px solid var(--gray-200); box-shadow: var(--shadow); }
      .nav.open { display: flex; }
      .menu-toggle { display: block; }
      .section { padding: 56px 20px; }
      .section-title { font-size: 1.8rem; }
      .product-card { flex: 0 0 calc(50% - 10px); min-width: 200px; }
      .carousel-viewport { margin: 0 44px; }
      .cat-grid { grid-template-columns: repeat(2, 1fr); }
      .store-card { grid-template-columns: 1fr; gap: 4px; }
      .newsletter-form, .locator-form { flex-direction: column; }
      .footer-grid { grid-template-columns: 1fr 1fr; gap: 28px; }
      .seasonal-grid { grid-template-columns: 1fr 1fr; }
      .hero { padding: 60px 20px 80px; }
    }

    @media (max-width: 480px) {
      .product-card { flex: 0 0 85%; min-width: 0; }
      .cat-grid { grid-template-columns: 1fr 1fr; gap: 12px; }
      .highlights-grid { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: 1fr; }
      .seasonal-grid { grid-template-columns: 1fr; }
      .stat-number { font-size: 2.2rem; }
    }
  </style>
</head>
